int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<pair<int, int>> banks(n);
    for (int i = 0; i < n; i++) {
        string a, b;
        cin >> a >> b;
        banks[i] = {toMin(a), toMin(b)};
    }
    int q;
    cin >> q;
    vector<pair<int, int>> queries(q);
    for (int i = 0; i < q; i++) {
