import java.util.*;
import java.io.*;

public class Main {
    static boolean[] canTrade(int[][] banks, int[][] queries) {
        // banks and queries hold {start, end} as minutes since 00:00
        // Write your solution here
        return new boolean[queries.length];
    }

    static int toMin(String x) {
        return Integer.parseInt(x.substring(0, 2)) * 60 + Integer.parseInt(x.substring(3));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        int[][] banks = new int[n][2];
        for (int i = 0; i < n; i++) {
            banks[i][0] = toMin(st.nextToken());
            banks[i][1] = toMin(st.nextToken());
        }
        int q = Integer.parseInt(st.nextToken());
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            queries[i][0] = toMin(st.nextToken());
            queries[i][1] = toMin(st.nextToken());
        }
        boolean[] res = canTrade(banks, queries);
        StringBuilder sb = new StringBuilder();
        for (boolean r : res) sb.append(r ? "YES" : "NO").append("\n");
        System.out.print(sb);
    }
}
